TABLES['expanded']=(TABLES['expanded'][0],[['Gate','Marker','Clean QA','Attack QA','Any email']]+TABLES['expanded'][1][1:])
idx=next(i for i,(h,t) in enumerate(result_items) if h=='Expanded end-to-end security')
